// Demo mode (debug build, NSPTONUP_MOCK=1): simulated conversion tasks and logs. The game library is generated by src/mock.rs.
// The log format matches what real conversions write (command line, tool output, result).

import { concat, msg, type Msg } from "../i18n";
import { joinPath, env } from "../native";
import { contents, coverUrl, failureReason, game, gameWarnings, games, type Game } from "./library";
import { injectMockHistory, injectMockJobs, type LogLine } from "./queue";

const mockId = (titleId: string) => `00000000-0000-4000-8000-${titleId.slice(-12)}`;
const KEYS = "/Users/Shared/Switch/prod.keys";

/// Deterministic pseudo-random number from the Title ID (file counts are the same on every launch)
function hash(text: string): number {
  let value = 2166136261;
  for (const char of text) value = Math.imul(value ^ char.charCodeAt(0), 16777619) >>> 0;
  return value;
}

/// Same as the pipeline's logging: args containing spaces are quoted
const command = (tool: string, args: string[]) => `$ ${tool} ` + args.map((a) => (a.includes(" ") ? `"${a}"` : a)).join(" ");

/// Same as the log produced from nxpatch part lines by describe_part in src/nxpatch.rs
const part = (what: Msg, files: number): Msg => ({ key: "log_part_files", args: [what], count: files });

function extractLog(g: Game): LogLine[] {
  const work = joinPath(env.workDir.replace(/^~/, "/Users/Shared"), `job-${hash(g.id).toString(16)}`);
  const args = ["extract", "-k", KEYS, "--base", g.nspPath];
  for (const c of contents(g)) args.push(c.kind === "update" ? "--update" : "--dlc", c.nspPath);
  args.push("--out", `${work}/dump`);
  const files = 800 + (hash(g.titleId ?? g.id) % 4000);
  const lines: LogLine[] = [command("nxpatch", args), part(msg("log_part_base", "exefs"), 4), part(msg("log_part_base", "romfs"), files)];
  for (const c of contents(g)) {
    if (c.kind === "update") {
      const revision = String(c.version >>> 16);
      lines.push(part(msg("log_part_update", revision, "exefs"), 4), part(msg("log_part_update", revision, "romfs"), files + 37));
    } else {
      lines.push(part(msg("log_part_dlc", c.titleId), 12));
    }
  }
  return lines;
}

function finishedLog(g: Game): LogLine[] {
  const work = `job-${hash(g.id).toString(16)}`;
  const out = g.nupPath ?? `${g.name}.nup`;
  const pack = ["pack", `…/${work}/dump`, out, "--name", g.name];
  if (g.displayVersion) pack.push("--display-version", g.displayVersion);
  if (g.publisher) pack.push("--publisher", g.publisher);
  for (const [tag, value] of Object.entries(g.localizedNames).sort()) pack.push("--lang-name", `${tag}=${value}`);
  const lines = extractLog(g);
  const warning = gameWarnings(g)[0];
  if (warning) lines.push(msg("log_cover_error", msg("error_cover_not_in_library")));
  else if (coverUrl(g)) pack.push("--icon", coverUrl(g)!);
  lines.push(command("nup", pack), command("nup", ["verify", out]), "[nup] verify: OK (deep)", msg("log_generated", out));
  if (warning) lines.push(concat("⚠ ", warning));
  return lines;
}

/// Demo: Pikmin 4 converting (stuck at extraction), Kirby and Hades queued; finished and failed games each have one conversion record
export function injectMockData() {
  const running = game(mockId("0100B7C00933A000"));
  injectMockJobs(mockId("0100B7C00933A000"), [mockId("01004D300C5AE000"), mockId("0100535012974000")], running ? extractLog(running).slice(0, 2) : []);
  for (const g of games()) {
    if (g.id === running?.id) continue;
    if (g.status === "converted") injectMockHistory(g.id, finishedLog(g));
    else if (g.status === "failed") {
      const reason = failureReason(g);
      if (!reason) continue;
      const error: Msg = typeof reason === "string" ? { key: "text_raw", args: [reason] } : reason;
      // Insufficient disk space fails before starting; the others fail while extracting exefs / romfs
      const early = error.key === "error_disk_space";
      const failed = concat("✘ ", error);
      injectMockHistory(g.id, early ? [failed] : [extractLog(g)[0], failed], early ? 0 : 1, error);
    }
  }
}
